package com.herbpatch;

import com.herbpatch.constants.HerbPatch;
import com.herbpatch.constants.HerbStages;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import javax.inject.Inject;
import java.awt.*;
import java.util.Objects;

public class HerbPatchOverlay extends Overlay {
    private static final int MAX_DISTANCE = 2500;
    private static final int OVERLAY_PRIORITY = 0;

    private final Client client;
    private final HerbPatchPlugin plugin;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject private HerbPatchConfig config;
    @Inject private CompostStatus compostStatus;

    @Inject
    private HerbPatchOverlay(Client client, HerbPatchPlugin plugin, ModelOutlineRenderer modelOutlineRenderer) {
        this.plugin = plugin;
        this.client = client;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OVERLAY_PRIORITY);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        GameObject patchObject = plugin.getHerbPatchObject();
        if (Objects.isNull(patchObject)) {
            return null;
        }

        HerbPatch patch = HerbPatch.byObjectId(patchObject.getId());
        if (patch == null) return null;

        int state = client.getVarbitValue(patch.varbit);

        // If state is not default and user wants to render for current state -> render overlay
        if (state != -1) {
            Color color = getHerbOverlayColor(state, patch);
            if (!Objects.isNull(color)) {
                drawOverlay(patchObject, graphics, color);
            }
        }

        return null;
    }

    /**
     * Method to draw object overlay on screen. Should be run every frame.
     * @param object Object to draw overlay on/above
     * @param graphics Main Java AWT 2D graphics object
     * @param color Overlay main outline color
     */
    private void drawOverlay(GameObject object, Graphics2D graphics, Color color) {
        // Get player location and herb patch location
        LocalPoint herbLocation = object.getLocalLocation();
        LocalPoint playerLocation = client.getLocalPlayer().getLocalLocation();
        if (Objects.isNull(playerLocation)) {
            return;
        }

        // Check if herb patch is within set max distance
        if (playerLocation.distanceTo(herbLocation) <= MAX_DISTANCE) {
            Shape herb;
            // Set the overlay shape (object hull or tile)
            switch (config.overlaySelector()) {
                case TILE:
                    herb = Perspective.getCanvasTilePoly(client, herbLocation, object.getPlane());
                    break;
                case OUTLINE:
                    modelOutlineRenderer.drawOutline(object, config.outlineThickness(), color, config.outlineFeather());
                    return;
                case HULL:
                    herb = object.getConvexHull();
                    break;
                default:
                    return;
            }

            Point mousePosition = client.getMouseCanvasPosition();
            if (herb != null) {
                // Check if user is hovering the herb
                if (herb.contains(mousePosition.getX(), mousePosition.getY())) {
                    // Darken color if pointer is hovering herb
                    graphics.setColor(color.darker());
                } else {
                    graphics.setColor(color);
                }

                // Render overlay
                graphics.draw(herb);
                graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), config.fillAlpha()));
                graphics.fill(herb);
            }
        }
    }

    /**
     * Get the appropriate color based on herb state.
     * @param state The server controlled integer representing the state of the herb
     * @return The color to render the overlay
     * @see HerbStages
     */
    private Color getHerbOverlayColor(int state, HerbPatch patch) {
        switch (HerbStages.getHerbStage(state)) {
            case OVERGROWN:
                if (config.renderIfOvergrown()) {
                    return config.overgrownColor();
                }
                return null;
            case EMPTY:
                if (config.renderIfEmpty()) {
                    return config.emptyColor();
                }
                return null;
            case GROWING:
                return config.enableCompostColor() && compostStatus.isComposted(patch)
                    ? config.compostColor() : config.unripeColor();
            case GROWN:
                return config.matureColor();
            case DISEASED:
                return config.diseasedColor();
            case DEAD:
                return config.deadColor();
            default:
                return null;
        }
    }
}

package com.herbpatch;

import com.google.inject.Provides;
import com.herbpatch.constants.HerbPatch;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(
    name = "Herb Patch Colors",
    description = "Herb patch colors, compost highlighting, and an optional Herbs Ready HUD",
    tags = { "herblore", "farming", "timer" }
)
public class HerbPatchPlugin extends Plugin {
    @Inject private OverlayManager overlayManager;
    @Inject private HerbPatchOverlay herbOverlay;
    @Inject private HerbsReadyOverlay herbsReadyOverlay;

    @Getter(AccessLevel.PACKAGE)
    private GameObject herbPatchObject;

    @Provides
    HerbPatchConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(HerbPatchConfig.class);
    }

    @Override
    protected void startUp() {
        // Add HerbPatchOverlay to OverlayManager at start up
        overlayManager.add(herbOverlay);
        overlayManager.add(herbsReadyOverlay);
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(herbOverlay);
        overlayManager.remove(herbsReadyOverlay);
        herbPatchObject = null;
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        HerbPatch patch = HerbPatch.byObjectId(event.getGameObject().getId());
        if (patch == null) return;

        herbPatchObject = event.getGameObject();
        log.debug("Herb patch [{}] spawned", herbPatchObject.getId());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        // When changing state (e.g. teleporting) clear herb object
        if (event.getGameState() == GameState.LOADING) {
            herbPatchObject = null;
        }
    }
}

package com.herbpatch;

import com.herbpatch.constants.HerbPatch;
import java.time.Instant;
import java.util.EnumSet;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigManager;

/**
 * Read-only, per-RuneScape-profile summary from RuneLite Time Tracking data.
 * Values are snapshots that may be stale when patches have not been revisited.
 */
public class HerbReadinessTracker
{
    static final int TOTAL_PATCHES = HerbPatch.values().length;
    private static final String TRACKING_GROUP = "timetracking";
    private static final long REFRESH_SECONDS = 5L;

    private final Client client;
    private final ConfigManager configManager;

    private String cachedProfileKey;
    private long lastReadSeconds = Long.MIN_VALUE;
    private Readiness cached = new Readiness(0, 0);

    @Inject
    public HerbReadinessTracker(Client client, ConfigManager configManager)
    {
        this.client = client;
        this.configManager = configManager;
    }

    Readiness getReadiness()
    {
        long now = Instant.now().getEpochSecond();
        String profile = configManager.getRSProfileKey();
        if (profile == null || profile.isEmpty())
        {
            return new Readiness(0, 0);
        }

        if (profile.equals(cachedProfileKey)
            && now >= lastReadSeconds && now - lastReadSeconds < REFRESH_SECONDS)
        {
            return cached;
        }

        int offset = parseNumberOrZero(configManager.getRSProfileConfiguration(
            TRACKING_GROUP, "farmTickOffset"));
        int precision = parseNumberOrZero(configManager.getRSProfileConfiguration(
            TRACKING_GROUP, "farmTickOffsetPrecision"));
        EnumSet<WorldType> worldTypes = client.getWorldType();
        boolean leagues = worldTypes != null
            && worldTypes.contains(WorldType.SEASONAL)
            && !worldTypes.contains(WorldType.DEADMAN);

        int ready = 0;
        int known = 0;
        for (HerbPatch patch : HerbPatch.values())
        {
            String key = patch.trackingRegionId + "." + patch.varbit;
            String record = configManager.getRSProfileConfiguration(TRACKING_GROUP, key);
            HerbReadyEstimator.Result result =
                HerbReadyEstimator.predict(record, now, offset, precision, leagues);
            if (result != HerbReadyEstimator.Result.UNKNOWN)
            {
                known++;
            }
            if (result == HerbReadyEstimator.Result.READY)
            {
                ready++;
            }
        }

        cachedProfileKey = profile;
        lastReadSeconds = now;
        cached = new Readiness(ready, known);
        return cached;
    }

    private static int parseNumberOrZero(String input)
    {
        if (input == null)
        {
            return 0;
        }
        try
        {
            return Integer.parseInt(input);
        }
        catch (NumberFormatException ignored)
        {
            return 0;
        }
    }

    static final class Readiness
    {
        final int ready;
        final int known;

        Readiness(int ready, int known)
        {
            this.ready = ready;
            this.known = known;
        }

        boolean allReady()
        {
            return ready == TOTAL_PATCHES;
        }

        int remaining()
        {
            return TOTAL_PATCHES - ready;
        }
    }
}

package com.herbpatch;

/**
 * Predicts maturity from RuneLite Time Tracking's saved herb patch observations.
 * Data describes the last observed patch state, not an authoritative remote state.
 */
final class HerbReadyEstimator
{
    // RuneLite FarmingTracker/PatchImplementation.HERB herb varieties.
    private static final int[] GROWING_STARTS = {
        4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103
    };

    private static final int[] MATURE_STARTS = {
        8, 15, 22, 29, 36, 43, 50, 57, 64, 72, 79, 86, 93, 100, 107
    };

    enum Result
    {
        READY,
        GROWING,
        OTHER,
        UNKNOWN
    }

    private HerbReadyEstimator()
    {
    }

    static Result predict(String record, long nowSeconds,
                          int offsetMinutes, int offsetPrecisionMinutes,
                          boolean leaguesWorld)
    {
        if (record == null)
        {
            return Result.UNKNOWN;
        }

        String[] parts = record.split(":", -1);
        if (parts.length != 2)
        {
            return Result.UNKNOWN;
        }

        final int value;
        final long observedAt;
        try
        {
            value = Integer.parseInt(parts[0]);
            observedAt = Long.parseLong(parts[1]);
        }
        catch (NumberFormatException e)
        {
            return Result.UNKNOWN;
        }

        if (observedAt <= 0 || observedAt > nowSeconds + 30L)
        {
            return Result.UNKNOWN;
        }

        for (int start : MATURE_STARTS)
        {
            if (value >= start && value < start + 3)
            {
                return Result.READY;
            }
        }

        for (int start : GROWING_STARTS)
        {
            if (value >= start && value < start + 4)
            {
                int stage = value - start;
                int tickMinutes = leaguesWorld ? 4 : 20;
                long tickSeconds = tickMinutes * 60L;
                long offsetSeconds = (offsetPrecisionMinutes >= tickMinutes || offsetPrecisionMinutes >= 40)
                    ? Math.floorMod(offsetMinutes, tickMinutes) * 60L : 0L;
                long observedTick = Math.floorDiv(observedAt + offsetSeconds, tickSeconds)
                    * tickSeconds - offsetSeconds;
                long readyAt = observedTick + (4L - stage) * tickSeconds;
                return nowSeconds >= readyAt ? Result.READY : Result.GROWING;
            }
        }

        // Known but not harvestable: empty, weeds, diseased, dead, or goutweed.
        if (value >= 0 && value <= 255 && value != 220)
        {
            return Result.OTHER;
        }
        return Result.UNKNOWN;
    }
}

package com.herbpatch;

/** Determines whether the optional herb status indicator should be visible. */
final class HerbsReadyHudState
{
    enum State
    {
        HIDDEN,
        READY,
        NOT_READY
    }

    private HerbsReadyHudState()
    {
    }

    static State resolve(boolean hudEnabled, boolean allReady, boolean showNotReady)
    {
        if (!hudEnabled)
        {
            return State.HIDDEN;
        }
        if (allReady)
        {
            return State.READY;
        }
        return showNotReady ? State.NOT_READY : State.HIDDEN;
    }
}

package com.herbpatch;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Compact herb readiness indicator. RuneLite manages its position via Alt-drag.
 */
public class HerbsReadyOverlay extends Overlay
{
    static final int BASE_WIDTH = 130;
    static final int BASE_HEIGHT = 84;
    private static final int LEAF_WIDTH = 46;
    private static final int LEAF_HEIGHT = 34;
    private static final BufferedImage LEAF_ICON = loadLeafIcon();

    private final Client client;
    private final HerbPatchConfig config;
    private final HerbReadinessTracker tracker;

    @Inject
    public HerbsReadyOverlay(Client client, HerbPatchConfig config, HerbReadinessTracker tracker)
    {
        this.client = client;
        this.config = config;
        this.tracker = tracker;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !config.showHerbsReadyHud())
        {
            return null;
        }

        HerbsReadyHudState.State state = HerbsReadyHudState.resolve(
            true, tracker.getReadiness().allReady(), config.showNotReadyState());
        if (state == HerbsReadyHudState.State.HIDDEN)
        {
            return null;
        }
        final boolean ready = state == HerbsReadyHudState.State.READY;

        final double scale = Math.max(75, Math.min(150, config.herbsHudScalePercent())) / 100.0;
        final int width = (int) Math.round(BASE_WIDTH * scale);
        final int height = (int) Math.round(BASE_HEIGHT * scale);
        final Color background = ready ? config.herbsHudReadyColor() : config.herbsHudNotReadyColor();
        final Color textColor = config.herbsHudTextColor();
        final String label = ready ? "Herbs Ready" : "Not Ready";

        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.scale(scale, scale);
            int alpha = Math.max(0, Math.min(100, config.herbsHudOpacity())) * 255 / 100;
            g.setColor(new Color(background.getRed(), background.getGreen(), background.getBlue(), alpha));
            g.fillRect(0, 0, BASE_WIDTH, BASE_HEIGHT);

            g.setColor(Color.BLACK);
            g.setStroke(new BasicStroke(2f));
            g.drawRect(1, 1, BASE_WIDTH - 2, BASE_HEIGHT - 2);

            g.setColor(textColor);
            g.setFont(new Font(Font.DIALOG, Font.BOLD, 13));
            FontMetrics fm = g.getFontMetrics();
            g.drawString(label, (BASE_WIDTH - fm.stringWidth(label)) / 2, 17);

            if (LEAF_ICON != null)
            {
                // Preserve the original pixel-art appearance of the leaf icon.
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                    RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                g.drawImage(LEAF_ICON, (BASE_WIDTH - LEAF_WIDTH) / 2, 31,
                    LEAF_WIDTH, LEAF_HEIGHT, null);
            }
        }
        finally
        {
            g.dispose();
        }
        return new Dimension(width, height);
    }

    private static BufferedImage loadLeafIcon()
    {
        try (InputStream stream = HerbsReadyOverlay.class.getResourceAsStream(
            "/com/herbpatch/herb-leaf.png"))
        {
            if (stream == null)
            {
                return null;
            }
            return ImageIO.read(stream);
        }
        catch (IOException e)
        {
            return null;
        }
    }
}

package com.herbpatch.constants;

import java.util.Arrays;
import java.util.Map;
import java.util.stream.Collectors;

import static net.runelite.api.gameval.ObjectID.*;
// Transmog controllers for various farming patches
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_A; // Troll Stronghold, Weiss
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_B; // Harmony Island
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_D; // Falador, Port Phasmatys, Hosidius, Ardougne, Catherby, Varlamore
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_E; // Farming Guild

/**
 * Enum containing ObjectIDs and VarbitIDs for the various herb patches around Gilenor
 */
public enum HerbPatch {
